S = "Hakeem Force Academy"
QS = [
(S, "Who is traditionally credited in Pakistani textbooks with inventing the telescope?", ["Isaac Newton", "Galileo Galilei", "Johannes Kepler", "Edwin Hubble"], 1, "Galileo Galilei built and used an improved telescope in 1609 to observe the Moon, Jupiter's moons and the planets. Textbooks therefore credit him with the telescope.", "Sources differ: the Dutch spectacle maker Hans Lippershey filed the first known patent for a telescope in 1608.", [107]),
(S, "What is the SI unit of temperature?", ["Celsius", "Fahrenheit", "Kelvin", "Joule"], 2, "The kelvin (K) is the base SI unit of temperature. Celsius and Fahrenheit are not SI units.", "0 K is called absolute zero, equal to minus 273.15 degrees Celsius.", [3704, 512]),
(S, "Which letter appears three times in the word 'temperature' but only once in the word 'cylinder'?", ["T", "R", "E", "U"], 2, "In 'temperature' the letter E appears 3 times (t-E-mp-E-ratur-E) while T and R appear twice. In 'cylinder' E appears once.", "The word 'temperature' has 11 letters.", [4495]),
(S, "Which is the largest temple in the world?", ["Angkor Wat", "Borobudur", "Meenakshi Temple", "Brihadeeswarar Temple"], 0, "Angkor Wat in Cambodia covers about 162 hectares and is the largest religious monument in the world.", "Angkor Wat was built in the 12th century by King Suryavarman II, first as a Hindu and later a Buddhist temple.", [980, 496, 1147, 4452]),
(S, "In which province of Pakistan is the Thar desert mainly located?", ["Sindh", "Punjab", "Balochistan", "Khyber Pakhtunkhwa"], 0, "The Pakistani part of the Thar desert lies in the south-east of Sindh, mainly in Tharparkar district.", "The Thar desert extends into the Indian state of Rajasthan and is one of the most densely populated deserts in the world.", [2294, 4212]),
(S, "What was the old name of Thailand?", ["Burma", "Siam", "Ceylon", "Annam"], 1, "Thailand was officially known as Siam until 1939, and again briefly from 1945 to 1949.", "The Gulf of Thailand was formerly called the Gulf of Siam.", [1062]),
(S, "If (x, 1) = (1, y), what is the ordered pair (x, y)?", ["(1, 1)", "(0, 1)", "(1, 0)", "(y, x)"], 0, "Two ordered pairs are equal when their corresponding elements are equal, so x = 1 and y = 1. Hence (x, y) = (1, 1).", "The Cartesian product A x B is the set of all ordered pairs (a, b) with a in A and b in B.", [1966]),
(S, "Ali is 5 years old and his sister is three times his age. How old will his sister be when Ali is 12 years old?", ["19 years", "36 years", "20 years", "22 years"], 3, "The sister is 3 x 5 = 15 years old now. When Ali is 12 she is 15 + (12 - 5) = 22 years old.", "The age difference between two people always stays the same over the years.", [2025]),
(S, "If today is Friday, what day of the week will it be after 30 days?", ["Saturday", "Sunday", "Monday", "Friday"], 1, "30 divided by 7 leaves remainder 2. Two days after Friday is Sunday.", "A week has 7 days, so the weekday repeats every 7 days.", [2086]),
(S, "If today is Monday, what day will it be after 15 days?", ["Monday", "Wednesday", "Tuesday", "Sunday"], 2, "15 divided by 7 leaves remainder 1. One day after Monday is Tuesday.", "After 14 days the same weekday comes back.", [2088]),
(S, "If the 1st day of a month is Monday, what will be the day after tomorrow (counting today as the 1st)?", ["Tuesday", "Wednesday", "Thursday", "Friday"], 1, "Tomorrow is Tuesday (2nd), and the day after tomorrow is Wednesday (3rd).", "The 8th, 15th, 22nd and 29th of that month also fall on Monday.", [2049]),
(S, "In which city is the tomb of the Pashto poet Rehman Baba located?", ["Peshawar", "Swat", "Mardan", "Kohat"], 0, "The shrine of Rehman Baba is at Hazar Khwani on the outskirts of Peshawar.", "Rehman Baba (1650-1715) is a famous Sufi poet of the Pashto language.", [2186, 4213]),
(S, "Which major battle in which the Holy Prophet (PBUH) participated took place in 7 AH?", ["Battle of Khyber", "Battle of Badr", "Battle of Uhud", "Battle of Hunain"], 0, "The Battle of Khyber against the Jews of Khyber was fought in 7 AH (628 AD).", "The Conquest of Makkah came later, in 8 AH.", [4271]),
(S, "Who is Pakistan's highest run scorer in Test cricket?", ["Javed Miandad", "Inzamam-ul-Haq", "Mohammad Yousuf", "Younis Khan"], 3, "Younis Khan scored 10,099 Test runs and is the leading Pakistani Test run scorer.", "He passed Javed Miandad's 8,832 runs in 2015 and was the first Pakistani to reach 10,000 Test runs.", [4615]),
(S, "What is the main subject (topic) of Sahih Bukhari?", ["Fiqh (law) only", "Hadith (sayings and actions of the Prophet)", "History of the caliphs", "Tafsir of the Quran"], 1, "Sahih Bukhari, compiled by Imam Bukhari, is a collection of authentic hadith of the Holy Prophet (PBUH).", "It is regarded as the most authentic book of hadith after the Quran.", [3780]),
(S, "What are two circles that touch each other at exactly one point called?", ["Concentric circles", "Tangent circles", "Intersecting circles", "Congruent circles"], 1, "Circles that meet at exactly one point are called tangent (touching) circles. They can touch externally or internally.", "Concentric circles share the same centre and never meet.", [2857]),
(S, "Which of these countries does not share a border with Pakistan?", ["Iran", "Afghanistan", "China", "Bangladesh"], 3, "Pakistan borders India, China, Afghanistan and Iran. Bangladesh is separated from Pakistan by India.", "Bangladesh was East Pakistan until 1971.", [4279]),
(S, "Which tennis tournament is played on grass courts?", ["French Open", "Wimbledon", "US Open", "Australian Open"], 1, "Wimbledon in London is the only Grand Slam tennis tournament played on grass.", "The French Open is played on clay.", [4718]),
(S, "Which country has won the most ICC Cricket World Cup (ODI) titles?", ["India", "West Indies", "Pakistan", "Australia"], 3, "Australia has won the ODI Cricket World Cup six times (1987, 1999, 2003, 2007, 2015, 2023).", "India and West Indies have won it twice each, and Pakistan once in 1992.", [1125]),
(S, "What is a synonym of the word 'transparent'?", ["Clear", "Opaque", "Dark", "Thick"], 0, "Transparent means allowing light to pass through so things can be seen clearly. Clear is the closest synonym.", "Translucent means light passes through but objects cannot be seen clearly.", [3012]),
(S, "What is the antonym of 'transparent'?", ["Clear", "Opaque", "Glassy", "Visible"], 1, "Transparent means see-through, so its opposite is opaque, which does not let light through.", "Wood and metal are opaque materials.", [292]),
(S, "What is the order of the transpose of a matrix of order m x n?", ["m x n", "n x n", "m x m", "n x m"], 3, "The transpose is obtained by interchanging rows and columns, so an m x n matrix becomes n x m.", "The transpose of the transpose of a matrix gives back the original matrix.", [3801, 1989]),
(S, "The word 'terrorism' was first used in connection with which historical event?", ["The French Revolution", "The American Civil War", "The Russian Revolution", "The First World War"], 0, "The term came into use in the 1790s for the Reign of Terror of the Jacobins in revolutionary France.", "Sources differ on the exact year, with 1794 and 1795 both quoted.", [754, 5048, 539, 4833]),
(S, "What is the term of office of the President of Pakistan?", ["3 years", "4 years", "5 years", "6 years"], 2, "Under the 1973 Constitution the President of Pakistan is elected for a term of five years.", "A person cannot hold the office of President for more than two consecutive terms.", [3378]),
]
